window.EXPLAIN=window.EXPLAIN||{};window.EXPLAIN.pl={"10081":{"law":"art. 31 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Pojazdu z niesprawnym układem kierowniczym nie wolno holować w żaden sposób, bo nie da się nim kierować za pojazdem ciągnącym. Taki pojazd przewozi się na lawecie."},"10109":{"law":"art. 31 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Holowany motocykl musi mieć sprawne oba układy hamulcowe, przedni i tylny, bo sam odpowiada za swoje hamowanie. Prędkość nie ma tu znaczenia."},"10805":{"law":"art. 5 ust. 1 Prawa o ruchu drogowym","text":"Poleceń pilota pojazdu nienormatywnego trzeba słuchać tak samo jak sygnałów policjanta, bo pilot kieruje ruchem na czas przejazdu ponadgabarytu. Jego sygnały mają pierwszeństwo przed znakami."},"10806":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Fotelik tyłem do kierunku jazdy na przednim siedzeniu jest dopuszczalny tylko przy wyłączonej poduszce pasażera. Otwierająca się poduszka uderza wtedy prosto w głowę dziecka."},"10815":{"text":"Fotelik montuje się dokładnie tak, jak opisał producent, bo tylko w tej konfiguracji przeszedł badania zderzeniowe. Wygoda i estetyka nie mają tu nic do rzeczy."},"10816":{"law":"art. 135 ust. 1 pkt 1a Prawa o ruchu drogowym","text":"Policjant zatrzymuje prawo jazdy przy przekroczeniu prędkości o więcej niż 50 km/h w obszarze zabudowanym. Równo 50 km/h to jeszcze nie ten przypadek, a poza obszarem zabudowanym przepis nie działa."},"10819":{"text":"Decyzję o zatrzymaniu prawa jazdy starosta wydaje przy przekroczeniu o więcej niż 50 km/h w obszarze zabudowanym. Poza obszarem zabudowanym ten przepis nie obowiązuje."},"10822":{"text":"Prawo jazdy zostaje zatrzymane na 3 miesiące. Jeśli kierowca mimo tego prowadzi, okres wydłuża się do 6 miesięcy, a przy kolejnym złamaniu zakazu grozi cofnięcie uprawnień."},"10829":{"law":"art. 71 ust. 1 Prawa o ruchu drogowym","text":"Dopuszczenie pojazdu do ruchu stwierdza dowód rejestracyjny. Karta pojazdu dokumentuje jego historię, a nalepki kontrolnej od 2019 roku już się nie stosuje."},"10840":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Dziecko niższe niż 150 cm przewozi się w foteliku lub innym urządzeniu przytrzymującym, dobranym do jego wzrostu i wagi. Na kolanach pasażera nie wolno wozić dziecka nigdy."},"10869":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Dziecko niższe niż 150 cm musi jechać w foteliku albo w innym urządzeniu przytrzymującym, także z przodu. Bez urządzenia i bez zapiętych pasów wozić go nie wolno nigdzie."},"10871":{"text":"Fotelik montuje się zgodnie z instrukcją producenta, bo tylko tak działają jego zaczepy i pasy. Wygoda dorosłego czy dziecka nie zmienia zasad montażu."},"10872":{"text":"Urządzenie przytrzymujące montuje się w sposób zalecany przez producenta, bo tak zostało przebadane i dopuszczone. Improwizacja przy montażu przekreśla całą ochronę."},"10874":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Dziecko poniżej trzech lat wolno wozić tylko w aucie z pasami bezpieczeństwa i w foteliku. Bez pasów nie da się zamocować fotelika, więc takim pojazdem dziecka się nie przewozi."},"10876":{"text":"Fotelik dobiera się według warunków technicznych: homologacji, wzrostu i wagi dziecka. Wygoda i wygląd są drugorzędne, bo o ochronie decyduje zgodność z normą."},"10878":{"law":"art. 39 ust. 3a Prawa o ruchu drogowym","text":"Dziecko o wzroście co najmniej 135 cm wolno wozić na tylnym siedzeniu w samych pasach, jeżeli jego wzrost i masa uniemożliwiają użycie fotelika. Granicą jest 135 cm, nie 125 cm, i nie ma tu żadnego limitu prędkości."},"10880":{"law":"art. 39 ust. 3a Prawa o ruchu drogowym","text":"Warunkiem jest wzrost co najmniej 135 cm i to, że wzrost oraz masa dziecka uniemożliwiają użycie urządzenia przytrzymującego. Ograniczenie prędkości nie ma z tym nic wspólnego."},"10882":{"law":"art. 39 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Jeżeli dwoje dzieci jedzie już w fotelikach i trzeciego nie da się zamocować, trzecie dziecko powyżej 3 lat wolno przypiąć samymi pasami. Na kolanach dorosłego dziecka nie wozi się nigdy."},"10883":{"law":"art. 39 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Trzecie dziecko, dla którego zabrakło miejsca na urządzenie przytrzymujące, zabezpiecza się pasami bezpieczeństwa. Podstawka pod nogi ani miejsce na środku kanapy niczego nie zmieniają."},"10885":{"law":"art. 38 Prawa o ruchu drogowym","text":"Trzeba mieć przy sobie pokwitowanie zatrzymania dowodu rejestracyjnego, dopóki uprawnia ono do jazdy. Samego dowodu rejestracyjnego ani potwierdzenia opłaty OC wozić w Polsce nie trzeba, dane są w bazie."},"10886":{"law":"art. 38 Prawa o ruchu drogowym","text":"Wozi się pokwitowanie zatrzymania pozwolenia czasowego, dopóki uprawnia ono do używania pojazdu. Polisa AC jest dobrowolna, a zaświadczenia o badaniu technicznym nie trzeba mieć przy sobie."},"10887":{"law":"art. 38 Prawa o ruchu drogowym","text":"Od 2018 roku dowodu rejestracyjnego nie trzeba wozić, ale pokwitowanie jego zatrzymania już tak, bo to ono zastępuje wtedy dokument pojazdu. Policjant sprawdza dane w Centralnej Ewidencji Pojazdów."},"10888":{"law":"art. 38 Prawa o ruchu drogowym","text":"Obowiązkowe jest pokwitowanie zatrzymania pozwolenia czasowego w okresie, w którym uprawnia ono do jazdy. Świadectwa zgodności WE ani dowodu rejestracyjnego wozić nie trzeba."},"10889":{"law":"art. 38 pkt 3 Prawa o ruchu drogowym","text":"Kierując autem zarejestrowanym za granicą trzeba mieć dokument dopuszczający pojazd do ruchu, bo polskich baz danych ten pojazd nie ma. Ubezpieczenie NW jest dobrowolne, a kopia badania technicznego niczego nie zastępuje."},"10890":{"law":"art. 38 pkt 3 Prawa o ruchu drogowym","text":"Przy pojeździe zarejestrowanym za granicą wozi się dokument potwierdzający zawarcie obowiązkowego OC. Polskie bazy nie zawierają danych o ubezpieczeniu takiego auta."},"10891":{"law":"art. 38 pkt 3 Prawa o ruchu drogowym","text":"Przy aucie zarejestrowanym za granicą trzeba mieć dowód opłacenia składki OC. Opłaty za autostrady i dowód własności nie są dokumentami wymaganymi w kontroli drogowej."},"10892":{"law":"art. 38 pkt 1 Prawa o ruchu drogowym","text":"Polskiego prawa jazdy nie trzeba wozić, bo uprawnienia widnieją w ewidencji, ale dokument zagraniczny trzeba mieć przy sobie. Świadectwo kwalifikacji dotyczy tylko kierowców zawodowych."},"10893":{"law":"art. 38 Prawa o ruchu drogowym","text":"Pokwitowanie zatrzymania prawa jazdy trzeba mieć przy sobie, bo w tym czasie zastępuje ono dokument uprawniający do kierowania. Orzeczenia lekarskie i psychologiczne dotyczą kierowców zawodowych."},"10894":{"law":"art. 38 Prawa o ruchu drogowym","text":"Kierowca ma przy sobie pokwitowanie zatrzymania prawa jazdy przez okres, w którym ono uprawnia do jazdy. Orzeczenie psychologiczne i lekarskie nie są w tym wykazie dla zwykłego kierowcy."},"10895":{"law":"art. 38 pkt 1 Prawa o ruchu drogowym","text":"Obowiązkowy jest dokument uprawniający do kierowania inny niż polskie prawo jazdy, na przykład zagraniczne albo międzynarodowe. Zaświadczenia o kursach nie są dokumentami kontroli drogowej."},"10898":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Prawo jazdy zabiera się za przewożenie osób w liczbie przekraczającej liczbę miejsc wpisaną w dowodzie rejestracyjnym. Wyprzedzanie przez linię ciągłą i wymijanie na przejeździe to mandat i punkty, ale dokumentu za nie nie tracisz."},"10899":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Podstawą zatrzymania prawa jazdy jest przewożenie osób ponad liczbę miejsc wpisaną w pozwoleniu czasowym. Wyprzedzanie przed przejściem z kierowanym ruchem jest legalne, a wymijanie na przejeździe dla rowerzystów to wykroczenie bez utraty dokumentu."},"10930":{"text":"Pokwitowanie uprawnia do jazdy przez 24 godziny od zatrzymania prawa jazdy. Po tym czasie kierowanie pojazdem jest już jazdą bez uprawnień."},"10931":{"text":"Także tutaj pokwitowanie działa 24 godziny, niezależnie od tego, za co prawo jazdy zabrano. Termin liczy się od chwili zatrzymania dokumentu."},"10960":{"law":"art. 135 ust. 1a Prawa o ruchu drogowym","text":"Prawa jazdy nie zabiera się, jeśli przekroczenie prędkości służyło ratowaniu życia lub zdrowia. Przepis wprost wyłącza sytuacje działania w stanie wyższej konieczności."},"10961":{"law":"art. 135 ust. 1a Prawa o ruchu drogowym","text":"Policjant odstąpi od zatrzymania prawa jazdy, bo kierujący działał, żeby ratować ludzkie życie. Nie ma tu ani pouczenia z egzaminem kontrolnym, ani dodatkowego szkolenia."},"10992":{"law":"art. 39 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Trzecie dziecko wolno przypiąć samymi pasami tylko wtedy, gdy dwoje już siedzi w fotelikach, trzeciego nie da się zamontować, a dziecko ukończyło 3 lata. Sam wzrost 100 cm ani wiek 15 lat nie są tu warunkiem."},"10994":{"law":"art. 39 ust. 4 Prawa o ruchu drogowym","text":"Odstępstwo daje wyłącznie zaświadczenie lekarskie o przeciwwskazaniu do przewozu w foteliku. Brak miejsca na fotelik ani wzrost 135 cm nie zwalniają z obowiązku na przednim siedzeniu."},"11001":{"law":"art. 38 Prawa o ruchu drogowym","text":"Kierowca z uprawnieniem ograniczonym do auta z blokadą alkoholową musi wozić zaświadczenie o badaniu technicznym w tym zakresie. Dowodu rejestracyjnego ani potwierdzenia OC wozić nie trzeba."},"11003":{"text":"Inspektor transportu drogowego ma w tym zakresie takie same uprawnienia jak policja i może sprawdzić pojazd w Centralnej Ewidencji Pojazdów. Kontrola transportu bez dostępu do tych danych byłaby pozorna."},"11005":{"law":"art. 132 ust. 5 Prawa o ruchu drogowym","text":"Dowód rejestracyjny zwraca stacja kontroli pojazdów po badaniu odpowiadającym przyczynie zatrzymania. Dopiero potwierdzenie, że usterka zniknęła, przywraca dokument."},"11017":{"text":"Za przekroczenie prędkości o więcej niż 50 km/h w obszarze zabudowanym prawo jazdy zatrzymuje się na 3 miesiące. Jazda mimo zatrzymania wydłuża ten okres do 6 miesięcy."},"11018":{"text":"Pokwitowanie pozwala kierować przez 24 godziny od zatrzymania prawa jazdy. Ma to umożliwić dojazd do domu, a nie dalszą normalną jazdę."},"11022":{"law":"art. 135 ust. 1a Prawa o ruchu drogowym","text":"Wyjątkiem jest działanie w celu uchylenia bezpośredniego niebezpieczeństwa grożącego dobru chronionemu prawem, czyli stan wyższej konieczności. Presja innego kierowcy ani chęć szybszego zjechania ze skrzyżowania nie usprawiedliwiają niczego."},"11028":{"law":"art. 39 ust. 3 Prawa o ruchu drogowym","text":"Przy aktywnej poduszce pasażera dziecko wolno wozić z przodu tylko w foteliku ustawionym przodem do kierunku jazdy. Każde ustawienie tyłem wymaga wyłączenia poduszki."},"11528":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Przekroczenie liczby miejsc o dwie osoby lub więcej kosztuje zatrzymanie prawa jazdy na 3 miesiące. Kontrolne sprawdzenie kwalifikacji nie jest tu przewidziane."},"13052":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"Sztywno określony minimalny odstęp obowiązuje na autostradzie i drodze ekspresowej: co najmniej połowa liczby wskazanej przez prędkościomierz, wyrażona w metrach. Na innych drogach odstęp ma być po prostu bezpieczny."},"13054":{"law":"art. 20 ust. 5 Prawa o ruchu drogowym","text":"Pojazd z urządzeniem wystającym do przodu ponad 1,5 m od siedzenia kierowcy może jechać najwyżej 30 km/h w obszarze zabudowanym i 60 km/h poza nim. Wystający element zasłania drogę tuż przed autem, stąd obniżony limit."},"13058":{"law":"art. 19 ust. 1 i art. 20 ust. 3 Prawa o ruchu drogowym","text":"Na autostradzie samochód osobowy może jechać najwyżej 140 km/h, i to tylko wtedy, gdy warunki pozwalają panować nad pojazdem. Limit jest górną granicą, a nie prędkością zalecaną."},"13064":{"law":"art. 20 ust. 1 Prawa o ruchu drogowym","text":"W obszarze zabudowanym obowiązuje 50 km/h i dotyczy to również czterokołowca, niezależnie od jego masy. Masa zmienia limity dopiero poza obszarem zabudowanym i przy zestawach z przyczepą."},"13088":{"law":"art. 31 ust. 1 pkt 3 Prawa o ruchu drogowym","text":"Holować wolno najwyżej z prędkością 30 km/h w obszarze zabudowanym i 60 km/h poza nim. Pojazd holowany często ma słabsze hamulce i nie ma wspomagania, więc szybciej jest po prostu niebezpiecznie."},"13382":{"law":"art. 39 ust. 4 Prawa o ruchu drogowym","text":"Jedyny wyjątek daje zaświadczenie lekarskie o przeciwwskazaniu do przewożenia w foteliku. Wolniejsza jazda ani naklejka informująca o dziecku nie zwalniają z obowiązku."},"13402":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Biała laska oznacza osobę niewidomą, a wtedy kierujący ma obowiązek zatrzymać pojazd i umożliwić przejście, także poza przejściem dla pieszych. Sygnał dźwiękowy taką osobę tylko dezorientuje."},"13404":{"law":"art. 26 ust. 1 i 6 Prawa o ruchu drogowym","text":"Osoba z widoczną niepełnosprawnością potrzebuje więcej czasu, więc trzeba z góry założyć, że pojazd trzeba będzie zatrzymać. Dojeżdżanie do przejścia z prędkością, która na to nie pozwala, jest błędem."},"13460":{"law":"art. 28 ust. 6 Prawa o ruchu drogowym","text":"Jeżeli pojazdu nie da się usunąć z torowiska, trzeba ostrzec maszynistę, bo pociąg hamuje setki metrów. Ostrzega się z odpowiedniej odległości, dając wyraźny sygnał widoczny z lokomotywy."},"13461":{"law":"art. 28 ust. 5 i 6 Prawa o ruchu drogowym","text":"W pierwszej kolejności trzeba usunąć pojazd z przejazdu, a dopiero gdy się nie da, ostrzegać maszynistę. Kolejność jest taka, bo pusty przejazd rozwiązuje problem, a ostrzeżenie tylko go sygnalizuje."},"13463":{"text":"Zapory są tak zbudowane, żeby dało się je wyłamać, jeśli auto utknęło między nimi. Lepiej zniszczyć zaporę niż zostać na torach przed nadjeżdżającym pociągiem."},"13464":{"law":"art. 28 ust. 3 pkt 1 Prawa o ruchu drogowym","text":"Gdy półzapory zaczynają się opuszczać, wjazd na przejazd jest już zabroniony, bez względu na ostrożność. Opuszczanie oznacza, że pociąg jest w drodze i za chwilę będzie na przejeździe."},"13522":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Wobec osoby o widocznie ograniczonej sprawności ruchowej obowiązek zatrzymania działa także poza przejściem dla pieszych. Taka osoba nie zdąży ustąpić drogi ani cofnąć się przed nadjeżdżającym autem."},"13540":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Omijając pieszego trzeba zachować bezpieczny odstęp, a w razie potrzeby zmniejszyć prędkość. Pieszy może zrobić krok w bok, więc bliski przejazd z pełną prędkością jest wykluczony."},"13551":{"law":"art. 30 ust. 3 Prawa o ruchu drogowym","text":"We mgle poza obszarem zabudowanym kierujący pojazdem silnikowym daje krótkotrwałe sygnały dźwiękowe podczas wyprzedzania, także wyprzedzając pieszego. Pieszy nie usłyszy cichego auta i nie zdąży zejść z drogi."},"13552":{"law":"art. 30 ust. 3 Prawa o ruchu drogowym","text":"Ten sam obowiązek dotyczy omijania: we mgle poza obszarem zabudowanym daje się krótkotrwałe sygnały dźwiękowe. Chodzi o to, żeby pieszy usłyszał pojazd, zanim ten znajdzie się obok niego."},"13553":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Na przystanku bez wyspy pasażerowie wysiadają wprost na jezdnię, więc kierujący musi zatrzymać się tak, by mieli swobodne dojście do pojazdu. Przejazd obok stojącego autobusu bez zatrzymania jest wykroczeniem."},"13560":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Obowiązek jazdy z prędkością zapewniającą panowanie nad pojazdem dotyczy każdego kierującego, także rowerzysty i woźnicy. Nie zależy ani od rodzaju pojazdu, ani od obszaru."},"13561":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Prędkość bezpieczna to ta, przy której panujesz nad pojazdem w danych warunkach. Bywa znacznie niższa od dopuszczalnej, na przykład na oblodzonej drodze albo we mgle."},"13562":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Jedziesz tak szybko, żeby zatrzymać się przed przeszkodą na widocznym odcinku drogi, niezależnie od limitu. W nocy albo we mgle oznacza to prędkość znacznie niższą niż dopuszczalna."},"13569":{"text":"Im szybciej jedziesz, tym mniej czasu zostaje na dostrzeżenie zagrożenia i reakcję. Czas reakcji jest w przybliżeniu stały, więc przy większej prędkości auto przejeżdża w tym czasie dłuższy odcinek."},"13570":{"text":"Energia zderzenia rośnie z kwadratem prędkości, więc prędkość decyduje o skutkach każdego wypadku, nie tylko czołowego. Różnica między 50 a 70 km/h to różnica między stłuczką a wypadkiem śmiertelnym."},"13580":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Nocą na krętej, nieoświetlonej drodze światła sięgają krócej niż droga zatrzymania przy maksymalnym limicie. Trzeba jechać tak, żeby zatrzymać się w zasięgu własnych świateł."},"13592":{"text":"Pojazd jadący bardzo szybko trudniej zauważyć, bo inni oceniają odległość i czas dojazdu na podstawie typowych prędkości. Dlatego kierowca włączający się do ruchu wyjeżdża wprost przed rozpędzone auto."},"13593":{"text":"Przy 120 km/h auto pokonuje około 33 metry na sekundę, więc sekunda zwłoki to ponad trzydzieści metrów dłuższa droga zatrzymania. Tyle wystarczy, żeby zderzenia nie dało się już uniknąć."},"13594":{"text":"100 km/h to około 28 metrów na sekundę, bo dzieli się kilometry na godzinę przez 3,6. Warto pamiętać ten przelicznik: przy 50 km/h auto robi około 14 metrów na sekundę."},"13604":{"law":"art. 33a ust. 3 Prawa o ruchu drogowym","text":"Hulajnoga elektryczna jest przeznaczona dla jednej osoby i przewożenie pasażera jest zabronione. Druga osoba zmienia środek ciężkości i wydłuża drogę hamowania pojazdu, który i tak hamuje słabo."},"13609":{"law":"art. 60 ust. 2 pkt 4 Prawa o ruchu drogowym","text":"Ciągnięcie za pojazdem osoby na urządzeniu wspomagającym ruch, jak na hulajnodze czy rolkach, jest zabronione. Taka osoba nie ma jak hamować ani reagować na to, co robi kierowca."},"13615":{"law":"art. 33a ust. 2 Prawa o ruchu drogowym","text":"Z drogi dla pieszych wolno korzystać wyjątkowo, gdy nie ma drogi dla rowerów, a dopuszczalna prędkość na jezdni przekracza 30 km/h. Wtedy jedzie się z prędkością pieszego i ustępuje mu pierwszeństwa."},"13618":{"law":"art. 28 ust. 1 Prawa o ruchu drogowym","text":"Podniesione zapory nie zwalniają z obowiązku upewnienia się, czy pociąg nie nadjeżdża. Urządzenia zabezpieczające bywają uszkodzone, a odpowiedzialność za wjazd zawsze spoczywa na kierującym."},"13623":{"law":"art. 28 ust. 1 Prawa o ruchu drogowym","text":"Zbliżając się do przejazdu obserwuje się sygnalizację, zapory, sygnały dźwiękowe i sam tor w obie strony. Pociąg nie jest w stanie wyhamować, więc całe upewnienie się spoczywa na kierowcy."},"13684":{"text":"Rozwaga to zwiększenie uwagi tam, gdzie zagrożenie jest realne, czyli przy przejściu dla pieszych. Jazda stale na maksymalnym limicie ignoruje zmieniające się warunki, a maksymalne przyspieszenia zagrożenia nie zmniejszają."},"13769":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Odstęp minimum 1 metra obowiązuje przy wyprzedzaniu, a nie przy wymijaniu. Wymijanie to mijanie pojazdu jadącego z przeciwka i tam wymagany jest po prostu odstęp bezpieczny."},"13834":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Hulajnoga elektryczna jest objęta tą samą zasadą co rower: przy wyprzedzaniu co najmniej 1 metr odstępu. Hulajnoga łatwo traci stabilność na nierówności, więc bliski przejazd może ją przewrócić."},"13835":{"law":"art. 20 ust. 6 pkt 2 Prawa o ruchu drogowym","text":"Hulajnoga elektryczna może jechać najwyżej 20 km/h, niezależnie od tego, ile potrafi rozwinąć. Na drodze dla pieszych obowiązuje ją dodatkowo prędkość zbliżona do prędkości pieszego."},"13850":{"law":"art. 19 ust. 1 i art. 28 ust. 1 Prawa o ruchu drogowym","text":"Ulewa albo śnieżyca skracają widoczność akurat tam, gdzie trzeba dojrzeć nadjeżdżający pociąg. Dlatego przed przejazdem zwalnia się bardziej niż zwykle, żeby zdążyć się rozejrzeć i zatrzymać."},"13859":{"law":"art. 24 ust. 1 Prawa o ruchu drogowym","text":"Przed każdym wyprzedzaniem trzeba upewnić się, że jest dość widoczności i miejsca, i że manewr nikomu nie utrudni ruchu. To warunek bezwzględny, niezależny od rodzaju drogi i pory dnia."},"13862":{"law":"art. 24 ust. 7 pkt 3 Prawa o ruchu drogowym","text":"W obszarze zabudowanym wyprzedzanie pojazdu uprzywilejowanego jest zabronione. Taki pojazd może w każdej chwili zmienić tor jazdy albo gwałtownie przyspieszyć, a przechodnie patrzą na niego, nie na Ciebie."},"13863":{"law":"art. 24 ust. 1 Prawa o ruchu drogowym","text":"Wyprzedzanie zawsze wymaga szczególnej ostrożności, bo wjeżdżasz na pas, którym nie jedziesz, i tracisz część widoczności. To najbardziej wypadkowy manewr w ruchu drogowym."},"13866":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Kolumna pieszych podlega tej samej zasadzie co pojedynczy pieszy: przy wyprzedzaniu minimum 1 metr odstępu. Kolumna zajmuje więcej miejsca i jej krawędź może się przesunąć w każdej chwili."},"13880":{"law":"art. 33a ust. 3 Prawa o ruchu drogowym","text":"Holowanie jednej hulajnogi elektrycznej przez drugą jest zabronione. Obie stają się wtedy niesterowne, a hamowanie jednej z nich wyrzuca drugą z toru jazdy."},"13882":{"law":"art. 135 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Za wykroczenie, którym stworzono poważne zagrożenie bezpieczeństwa, sąd może orzec zakaz prowadzenia pojazdów, a policjant zatrzymać prawo jazdy. Liczy się skutek, nie tylko sam fakt przekroczenia limitu."},"13883":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Prędkość bezpieczna wynika z warunków, a nie z tabliczki: na oblodzonej drodze bezpieczne bywa 30 km/h tam, gdzie wolno jechać 90. Mieszczenie się w limicie samo w sobie nie czyni prędkości bezpieczną."},"13884":{"text":"Tak, to standardowa sankcja: przekroczenie o ponad 50 km/h w obszarze zabudowanym kosztuje 3 miesiące bez prawa jazdy. Do tego dochodzi wysoki mandat i punkty karne."},"13885":{"law":"art. 19 ust. 2 pkt 2 Prawa o ruchu drogowym","text":"Jazda bez uzasadnienia zbyt wolno jest zabroniona, bo blokuje ruch i prowokuje ryzykowne wyprzedzanie. Na drodze szybkiego ruchu wolno jadące auto bywa równie groźne jak rozpędzone."},"13886":{"text":"Karta parkingowa daje ulgi w parkowaniu i pozwala nie stosować się do wybranych znaków zakazu, ale nie podnosi limitu prędkości. Przepisów o prędkości nie zmienia żaden dokument."},"13891":{"law":"art. 39 ust. 2 Prawa o ruchu drogowym","text":"Z obowiązku zapinania pasów zwolniona jest między innymi osoba niepełnosprawna przewożona w wózku inwalidzkim. Poczucie skrępowania pasami żadnym zwolnieniem nie jest."},"13893":{"law":"art. 66 ust. 1 Prawa o ruchu drogowym","text":"Pojazd dopuszcza się do ruchu, jeżeli jest utrzymany tak, że nie zagraża jadącym ani innym uczestnikom ruchu. Klimatyzacja i przyciemniane szyby nie mają z dopuszczeniem nic wspólnego."},"13902":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"Na autostradzie odstęp to co najmniej połowa wskazania prędkościomierza w metrach, czyli przy 140 km/h aż 70 metrów, a nie 60. Reguła jest prosta: podziel prędkość na pół."},"13903":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"Na dwujezdniowej drodze ekspresowej wolno jechać 120 km/h, więc odstęp wynosi co najmniej 60 metrów, a nie 50. Zawsze liczy się połowa liczby z prędkościomierza."},"13904":{"law":"art. 19 ust. 3 Prawa o ruchu drogowym","text":"Reguła połowy prędkości obowiązuje na autostradzie i drodze ekspresowej dwujezdniowej, i nie stosuje się jej podczas wyprzedzania. Gdyby stosować ją przy wyprzedzaniu, manewru nie dałoby się w ogóle wykonać."},"13909":{"text":"Zużyty bieżnik odprowadza znacznie mniej wody niż nowy, więc opona wcześniej traci kontakt z asfaltem. Przy resztce bieżnika aquaplaning zaczyna się przy prędkości, przy której nowa opona jeszcze trzyma."},"13910":{"text":"Przy obfitym deszczu między oponą a asfaltem tworzy się warstwa wody i auto przestaje reagować na kierownicę oraz hamulec. To właśnie aquaplaning i kończy się utratą panowania nad pojazdem."},"13911":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Limit to górna granica, a nie gwarancja bezpieczeństwa: przy mgle albo gołoledzi nawet prędkość w granicach przepisu bywa za duża. Obowiązek panowania nad pojazdem działa niezależnie od znaków."},"13912":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Przepis wymienia wprost między innymi natężenie ruchu, obok rzeźby terenu, stanu i widoczności drogi, stanu pojazdu i warunków atmosferycznych. Prognoza pogody i własne doświadczenie w tym katalogu nie występują."},"13915":{"text":"Przy dużej prędkości wzrok skupia się daleko przed autem i pole widzenia gwałtownie się zawęża. To dlatego kierowca na szybkiej drodze przestaje rejestrować pobocze i wjazdy z boku."},"13916":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Wobec osoby o widocznie ograniczonej sprawności ruchowej obowiązek zatrzymania jest bezwarunkowy i działa również poza przejściem. Nie ma tu miejsca na ocenę, czy zdąży ona przejść."},"13917":{"text":"Miejsce dla osoby z niepełnosprawnością jest szersze właśnie po to, żeby dało się otworzyć drzwi i wyjechać wózkiem. Zajęcie nawet jego części niweczy cały sens takiego stanowiska."},"13918":{"text":"Siła odśrodkowa rośnie z kwadratem prędkości, więc na łuku każde przyspieszenie wypycha auto na zewnątrz zakrętu. Gdy przekroczy przyczepność opon, pojazd zjeżdża z toru jazdy."},"13919":{"text":"Podwojenie prędkości na zakręcie zwiększa siłę odśrodkową czterokrotnie, bo zależy ona od kwadratu prędkości. Dlatego niewielkie dodanie gazu w zakręcie robi znacznie większą różnicę, niż się wydaje."},"13920":{"text":"Koła ciężarówki wyrzucają na bok ścianę wody, która na moment całkowicie zasłania szybę. Dlatego przed wymijaniem zwalnia się i przygotowuje wycieraczki na najwyższy bieg."},"13921":{"text":"Ręce na kierownicy powinny być lekko ugięte w łokciach: wtedy da się wykonać pełny obrót kierownicą bez odrywania pleców od oparcia. Wyprostowane ręce odbierają precyzję, a mocno zgięte siłę."},"13923":{"text":"Zagłówek ustawiony na wysokość potylicy ogranicza gwałtowny odchył głowy przy uderzeniu w tył auta i chroni przed urazem kręgosłupa szyjnego. Zagłówek opuszczony do poziomu karku sam staje się dźwignią."},"13924":{"text":"Źle dobrana pozycja utrudnia manewrowanie: za daleko odsunięty fotel nie pozwala wcisnąć sprzęgła do końca, a za blisko blokuje ruch rąk. Ustawienie dobiera się indywidualnie, nie tylko w skrajnych położeniach."},"13925":{"text":"Ustawienie fotela decyduje o tym, czy dosięgniesz pedałów i wykonasz pełny obrót kierownicą, a także o tym, jak zadziała pas i poduszka. To element bezpieczeństwa, nie kwestia wygody."},"13926":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Sama prędkość to za mało: liczy się też promień łuku, stan i pochylenie nawierzchni, obciążenie auta i widoczność za zakrętem. Zakręt pokonuje się według tego, co widać, a nie według prędkościomierza."},"13927":{"text":"Bezpieczne pokonanie zakrętu zaczyna się przed nim: zwalniasz na prostej, wybierasz tor i dopiero wtedy skręcasz. Tor jazdy dobiera się tak, żeby jak najdłużej widzieć wyjście z zakrętu."},"13928":{"text":"Jedna ręka na kierownicy nie poprawia precyzji, tylko ją odbiera: nie da się szybko oddać kierownicy ani zareagować na szarpnięcie. Kierownicę trzyma się obiema rękami, w pozycji jak wskazówki na godzinie dziewiątej i trzeciej."},"13929":{"text":"Ręka włożona do wewnątrz koła kierownicy zostaje uderzona przez otwierającą się poduszkę i traci kontakt z kierownicą przy szarpnięciu. Dotyczy to każdej sytuacji, nie tylko parkowania."},"13932":{"law":"art. 135 ust. 1 pkt 1a Prawa o ruchu drogowym","text":"Tak, przy przekroczeniu o więcej niż 50 km/h w obszarze zabudowanym policjant zatrzymuje prawo jazdy na miejscu, za pokwitowaniem. Pokwitowanie pozwala jechać jeszcze 24 godziny."},"13936":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Limit mówi tylko, ile najwyżej wolno, a nie ile w danej chwili jest bezpiecznie. We mgle, na mokrym asfalcie albo w tłoku prędkość zapewniająca panowanie nad autem jest znacznie niższa."},"13941":{"law":"art. 4 i art. 45 Prawa o ruchu drogowym","text":"Widząc niebezpieczne zachowanie na drodze, ostrzegasz innych, na przykład światłami awaryjnymi, i w miarę możliwości usuwasz zagrożenie. Zasada ograniczonego zaufania działa w obie strony: przewidujesz i uprzedzasz."},"13942":{"law":"art. 2 pkt 47b Prawa o ruchu drogowym","text":"Z definicji hulajnoga elektryczna nie ma siedzenia, jazda odbywa się na stojąco. Pojazd z siedzeniem to już inna kategoria, na przykład motorower, i podlega innym przepisom."},"13943":{"law":"art. 4 Prawa o ruchu drogowym","text":"Ostrzeżenie daje innym czas na reakcję i może zapobiec kolejnym zdarzeniom, na przykład najechaniu na rozlany olej. Nie zwalnia jednak z odpowiedzialności i nie gwarantuje, że nic się nie stanie."},"13944":{"law":"art. 3a ust. 2 ustawy o kierujących pojazdami","text":"Poza strefą zamieszkania hulajnogą elektryczną może jechać osoba od 10 lat, która ma kartę rowerową. Od 18 lat żaden dokument nie jest już potrzebny, a w strefie zamieszkania wieku się nie wymaga."},"13945":{"text":"Ubezpieczyciele biorą pod uwagę historię wykroczeń, więc mandaty za prędkość podnoszą składkę OC przy odnowieniu. Utrata zniżek bywa dotkliwsza niż sam mandat."},"13950":{"text":"Niepełnosprawność nie znaczy, że ktoś złamie przepisy, i takiego założenia się nie robi. Trzeba natomiast liczyć się z tym, że taka osoba może potrzebować więcej czasu i nie zdąży ustąpić."},"13951":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Przy wyprzedzaniu hulajnogi elektrycznej obowiązuje co najmniej 1 metr, a nie 0,5 metra. Ta sama odległość dotyczy roweru, motoroweru, motocykla i pieszego."},"13962":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Urządzenie wspomagające ruch, jak rolki czy deskorolka, jest objęte tą samą regułą: minimum 1 metr przy wyprzedzaniu. Osoba na takim urządzeniu ma jeszcze mniej stabilności niż rowerzysta."},"13975":{"law":"art. 26 ust. 3 pkt 2 Prawa o ruchu drogowym","text":"Na przejściu dla pieszych o ruchu niekierowanym i bezpośrednio przed nim wyprzedzanie jest zabronione. Wyprzedzający zasłania widok i ani on nie widzi pieszego, ani pieszy jego."},"13976":{"law":"art. 26 ust. 3 pkt 2 Prawa o ruchu drogowym","text":"Zakaz dotyczy przejść o ruchu niekierowanym, więc tam, gdzie ruchem kieruje sygnalizacja albo policjant, wyprzedzanie jest dopuszczalne. Sygnalizacja rozdziela ruch pieszych i pojazdów w czasie."},"13985":{"law":"art. 26 ust. 1 Prawa o ruchu drogowym","text":"Osoba pchająca urządzenie wspomagające ruch jest pieszym, więc wchodząc na przejście ma pierwszeństwo. Prowadzenie roweru czy hulajnogi obok siebie nie zmienia statusu pieszego."},"13986":{"law":"art. 26 ust. 1 Prawa o ruchu drogowym","text":"Wobec pieszego znajdującego się na przejściu obowiązuje szczególna ostrożność i ustąpienie pierwszeństwa. Osoba pchająca urządzenie wspomagające ruch jest traktowana jak każdy inny pieszy."},"13987":{"law":"art. 51 ust. 3 Prawa o ruchu drogowym","text":"Świateł drogowych nie wolno używać, jeśli mogą oślepić kogokolwiek, także pieszych idących w kolumnie. Oślepiona kolumna traci orientację i może zejść na jezdnię."},"13991":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Specjalny znak, czyli biała laska lub opaska z trzema kropkami, oznacza osobę niewidomą. Wobec niej obowiązek zatrzymania pojazdu działa wszędzie, także poza przejściem."},"13992":{"law":"art. 26 ust. 6 Prawa o ruchu drogowym","text":"Osoba o widocznej ograniczonej sprawności ruchowej ma prawo przejść, a kierujący ma obowiązek się zatrzymać. Przepis nie wymaga tu ani przejścia dla pieszych, ani żadnego dokumentu."},"13993":{"text":"Przejście sugerowane nie jest przejściem dla pieszych w rozumieniu przepisów, więc pierwszeństwa tam nie ma. Nie zwalnia to jednak z ostrożności, bo pieszy i tak może tam wejść na jezdnię."},"13994":{"law":"art. 4 Prawa o ruchu drogowym","text":"Przejście sugerowane wygląda jak miejsce do przechodzenia, więc pieszy często wchodzi tam bez wahania. Zasada ograniczonego zaufania każe założyć, że tak właśnie zrobi, i zawczasu zwolnić."},"13995":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Wymijając pieszego trzeba w razie potrzeby zjechać w prawo, zwolnić, a nawet się zatrzymać. Pieszy na wąskiej drodze nie ma dokąd uciec, więc to kierujący ustępuje miejsca."},"14002":{"law":"art. 26 ust. 1 Prawa o ruchu drogowym","text":"Osoba pchająca urządzenie wspomagające ruch to pieszy, a pieszy wchodzący na przejście ma pierwszeństwo. Kierujący ma obowiązek ustąpić, a nie ocenić, czy zdąży przejechać."},"14007":{"law":"art. 4 i art. 45 Prawa o ruchu drogowym","text":"Rozlany olej to śmiertelna pułapka zwłaszcza dla motocyklistów, więc trzeba ostrzec innych i wezwać służby. Odjechanie i milczenie jest porzuceniem zagrożenia, które sam stworzyłeś."},"14015":{"law":"art. 19 ust. 1 Prawa o ruchu drogowym","text":"Zmęczenie, choroba czy stres wydłużają czas reakcji, więc prędkość bezpieczna dla tego samego kierowcy zmienia się z dnia na dzień. Po nocnej zmianie bezpieczna prędkość jest niższa niż po wypoczynku."},"14062":{"law":"art. 102 ust. 1d ustawy o kierujących pojazdami","text":"Jazda mimo przedłużonego do sześciu miesięcy zatrzymania kończy się cofnięciem uprawnień na 5 lat. Po tym okresie prawo jazdy trzeba zdobyć od nowa, ze wszystkimi egzaminami."},"14063":{"law":"art. 102 ust. 1d ustawy o kierujących pojazdami","text":"Skutek jest ten sam niezależnie od tego, za co prawo jazdy zabrano: cofnięcie uprawnień na 5 lat. Liczy się to, że kierowca prowadził mimo obowiązującego zakazu."},"14064":{"law":"art. 135 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Prawo jazdy zabiera się, gdy liczba przewożonych osób przekracza liczbę miejsc o więcej niż dwie, czyli o trzy i więcej. Jedna czy dwie osoby ponad stan to mandat i punkty, ale bez utraty dokumentu."},"14107":{"law":"art. 33b ust. 2 Prawa o ruchu drogowym","text":"Po przejściu dla pieszych nie wolno przejeżdżać wzdłuż urządzeniem transportu osobistego, trzeba przez nie przejść, prowadząc urządzenie. Przejście jest przeznaczone do przechodzenia, a nie do przejazdu."},"1864":{"law":"art. 6 ust. 1 pkt 3 ustawy o kierujących pojazdami","text":"Czterokołowiec inny niż lekki (do 400 kg, silnik ponad 15 kW) wymaga kategorii B1. Kategoria AM obejmuje tylko czterokołowce lekkie, a kategoria A dotyczy motocykli."},"1866":{"law":"art. 81 Prawa o ruchu drogowym","text":"Właściciel ma obowiązek poddawać pojazd okresowym badaniom technicznym. Ubezpieczenia NW i Autocasco są dobrowolne, obowiązkowe jest tylko OC."},"1876":{"text":"Ciśnienie sprawdza się na zimnych oponach, bezpośrednio przed jazdą. Po jeździe opony są nagrzane i wskazanie jest zawyżone, a doba wcześniej ciśnienie może się jeszcze zmienić."},"1877":{"law":"art. 61 Prawa o ruchu drogowym","text":"Ładunek nie może naruszać stateczności pojazdu. Nie wolno też zasłaniać świateł ani tablic rejestracyjnych i zawsze trzeba go zabezpieczyć przed zmianą położenia."},"1878":{"law":"art. 61 ust. 1 Prawa o ruchu drogowym","text":"Ładunek zawsze zabezpiecza się przed przemieszczaniem. Niska prędkość niczego nie zmienia, bo wystarczy jedno hamowanie albo skręt, żeby ładunek się przesunął."},"1879":{"law":"art. 61 ust. 2 Prawa o ruchu drogowym","text":"Ładunek sypki przewozi się w szczelnej skrzyni zasłoniętej tak, żeby nie wysypywał się na drogę. Sama niska prędkość ani burty tego nie zapewniają."},"1880":{"law":"art. 61 ust. 1 Prawa o ruchu drogowym","text":"Urządzenie mocujące musi być zabezpieczone tak, żeby samo się nie rozluźniło podczas jazdy. Zwisający pas może wkręcić się w koło albo zahaczyć o inny pojazd."},"1881":{"law":"art. 61 ust. 3 Prawa o ruchu drogowym","text":"Ładunek nie może ograniczać kierującemu widoczności drogi. Nie wolno mu też zasłaniać świateł, odblasków ani tablic rejestracyjnych, nawet nieznacznie."},"1882":{"text":"Najcięższe rzeczy kładzie się jak najniżej, jak najgłębiej i centralnie. Ciężar wysoko lub z tyłu podnosi środek ciężkości i pogarsza stateczność auta na łuku i przy hamowaniu."},"1883":{"law":"art. 61 ust. 3 Prawa o ruchu drogowym","text":"Ładunek na przyczepie nie może zasłaniać jej świateł. Rozkłada się go też równomiernie, bo ładunek zsunięty na bok albo do tyłu psuje stateczność zestawu."},"1888":{"law":"art. 60 ust. 2 pkt 4 Prawa o ruchu drogowym","text":"Zabronione jest ciągnięcie za pojazdem osoby na nartach, sankach czy wrotkach. Radio CB jest dozwolone, a dziecko w foteliku z przodu wolno wozić po wyłączeniu poduszki powietrznej."},"1905":{"text":"Gaśnica musi być zamocowana i w zasięgu ręki kierującego, na przykład pod fotelem. Luźna gaśnica przy hamowaniu staje się pociskiem, a z tylnej półki nie da się jej szybko wyjąć."},"2025":{"text":"ASR to układ kontroli trakcji: przeciwdziała buksowaniu kół napędowych przy ruszaniu i przyspieszaniu. Blokowaniem kół podczas hamowania zajmuje się ABS."},"2026":{"text":"ESP stabilizuje tor jazdy, gdy auto zaczyna się znosić lub wpadać w poślizg na łuku. Za blokowanie kół odpowiada ABS, a za buksowanie przy ruszaniu ASR."},"2161":{"text":"Przy braku jałowego opatrunku użyj czystej odzieży poszkodowanego i uciśnij ranę. Zwłoka przy krwotoku jest groźniejsza niż niesterylny materiał."},"2164":{"text":"Opatrunek uciskowy zakłada się przy krwotoku, żeby zatrzymać wypływ krwi. Przy zmiażdżeniu kończyny i przy wycieku z ucha ucisku się nie stosuje."},"2535":{"text":"W deszczu przede wszystkim zmniejsz prędkość: rośnie droga hamowania i ryzyko aquaplaningu. Wyłączanie kontroli trakcji i jazda w koleinach tylko pogarszają sytuację."},"2536":{"text":"Po wjechaniu w koleinę z wodą zmniejsz prędkość płynnie, bez gwałtownych ruchów. Zdecydowane hamowanie lub przyspieszenie przy aquaplaningu kończy się utratą panowania nad autem."},"2538":{"text":"Na zaśnieżonej drodze bezpieczeństwo zwiększają opony zimowe, bo dają przyczepność w niskiej temperaturze. Hamulec ręczny blokuje tylną oś, a gwałtowne przyspieszanie powoduje buksowanie."},"3187":{"text":"Narkotyki w żadnej ilości nie poprawiają oceny ryzyka. Wydłużają czas reakcji, zaburzają ocenę odległości i prędkości oraz dają złudne poczucie pewności."},"3232":{"text":"Alkohol zawęża pole uwagi, więc podzielność uwagi spada i trudniej robić dwie rzeczy naraz. Właśnie dlatego kierowca po alkoholu przeocza pieszego, gdy patrzy na sygnalizator."},"3340":{"text":"Płynne ruszanie polega na stopniowym zwalnianiu sprzęgła przy delikatnym dodawaniu gazu. Gwałtowne puszczenie pedału gasi silnik albo szarpie autem."},"3353":{"law":"art. 45 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Zabronione jest korzystanie z telefonu, jeśli wymaga trzymania słuchawki lub mikrofonu w ręku. Zestaw głośnomówiący jest dozwolony, tempomat w terenie zabudowanym też."},"3429":{"text":"We mgle nocą przede wszystkim zmniejsz prędkość. Światła drogowe odbijają się od kropel wody i oślepiają, a jazda tuż za poprzedzającym autem nie zostawia miejsca na hamowanie."},"3523":{"text":"Przez rozległą kałużę przejeżdża się po płynnym zmniejszeniu prędkości. Gwałtowne hamowanie lub przyspieszenie na wodzie odrywa opony od nawierzchni."},"3573":{"law":"art. 44 ust. 2 Prawa o ruchu drogowym","text":"Świadek wypadku ma obowiązek zatrzymać się, wezwać pomoc medyczną i udzielić pierwszej pomocy. Ten obowiązek nie zależy od tego, kto spowodował wypadek."},"3625":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Przy wymijaniu przepis wymaga odstępu bezpiecznego, a nie konkretnej liczby metrów. Bezpieczny odstęp zależy od szerokości jezdni, prędkości i warunków ruchu."},"3626":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Jedyny odstęp podany w metrach dotyczy wyprzedzania roweru, motoroweru, motocykla i pieszego: co najmniej 1 metr. Przy innych manewrach obowiązuje odstęp bezpieczny."},"3627":{"law":"art. 23 ust. 1 pkt 1 Prawa o ruchu drogowym","text":"Przy omijaniu obowiązuje odstęp bezpieczny, zależny od szerokości jezdni i warunków ruchu. Przepis nie podaje tu żadnej stałej liczby metrów."},"3628":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Przy wyprzedzaniu samochodu osobowego obowiązuje odstęp bezpieczny, zależny od szerokości jezdni i warunków ruchu. Sztywny 1 metr dotyczy tylko roweru, motoroweru, motocykla i pieszego."},"3629":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Wyprzedzając motocykl trzeba zachować odstęp nie mniejszy niż 1 metr. Ta sama zasada dotyczy roweru, motoroweru i pieszego."},"3630":{"law":"art. 24 ust. 2 Prawa o ruchu drogowym","text":"Kolumnę pieszych wyprzedza się z odstępem nie mniejszym niż 1 metr, tak samo jak pojedynczego pieszego czy rowerzystę."},"3634":{"text":"Droga hamowania rośnie z kwadratem prędkości, więc dwa razy szybciej to cztery razy dłuższa droga. Z 50 na 100 km/h hamowanie wydłuża się czterokrotnie, a nie dwukrotnie."},"3650":{"law":"art. 19 ust. 3a Prawa o ruchu drogowym","text":"Poza obszarem zabudowanym w tunelu dłuższym niż 500 metrów samochód osobowy utrzymuje odstęp co najmniej 50 metrów. Pojazdy powyżej 3,5 tony mają odstęp 80 metrów."},"3651":{"text":"Droga zatrzymania to droga reakcji plus droga hamowania, więc czas reakcji kierującego wpływa na nią wprost. Masa pasażerów przy samochodzie osobowym jest w tym rachunku pomijalna."},"3652":{"text":"Na drogę zatrzymania wprost wpływają prędkość i stan nawierzchni, bo od nich zależy przyczepność i energia, którą trzeba wytracić. Masa pasażera jest pomijalna."},"3658":{"law":"art. 44 ust. 2 Prawa o ruchu drogowym","text":"Obowiązek udzielenia pomocy nie zależy od kwalifikacji medycznych. Wystarczy zrobić to, co umiesz: zabezpieczyć miejsce, wezwać pomoc i wykonać podstawowe czynności ratunkowe."},"3723":{"text":"Obowiązkowym wyposażeniem samochodu osobowego w Polsce są trójkąt ostrzegawczy i gaśnica. Apteczka i koło zapasowe są zalecane, ale nie wymagane przepisami."},"3724":{"text":"Gaśnica należy do obowiązkowego wyposażenia samochodu osobowego, razem z trójkątem ostrzegawczym. Apteczka i koło zapasowe obowiązkowe nie są."},"3759":{"law":"art. 30 ust. 1 i 3 Prawa o ruchu drogowym","text":"We mgle wolno używać przednich świateł przeciwmgłowych, zamiast lub razem ze światłami mijania. Światła drogowe odbijają się od mgły i oślepiają, a same światła do jazdy dziennej nie wystarczają."},"3761":{"law":"art. 30 ust. 3 Prawa o ruchu drogowym","text":"We mgle poza obszarem zabudowanym podczas wyprzedzania kierujący ma obowiązek używać krótkotrwałych sygnałów dźwiękowych. Tylne światła przeciwmgłowe włącza się dopiero przy widoczności poniżej 50 metrów."},"3778":{"text":"Przy wymijaniu nocą patrz w prawo od reflektorów nadjeżdżającego auta i obserwuj tam pobocze. Patrzenie prosto w światła oślepia na kilka sekund, a przełączenie na drogowe oślepia drugiego kierowcę."},"3781":{"text":"Ksenonu nie wolno wkładać w reflektor zaprojektowany pod żarówkę halogenową. Reflektor rozprasza wtedy światło niezgodnie z homologacją i oślepia innych kierujących, nawet jeśli trzonek pasuje."},"3783":{"law":"art. 45 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Korzystanie z nawigacji podczas jazdy jest dozwolone. Zabronione są rozpinanie pasów i telefon wymagający trzymania słuchawki w ręku."},"3784":{"text":"Minimalna głębokość bieżnika to 1,6 milimetra. Poniżej tej wartości opona przestaje odprowadzać wodę i gwałtownie rośnie ryzyko aquaplaningu."},"3785":{"text":"Przepalony kierunkowskaz to usterka układu oświetlenia: inni kierujący nie widzą Twojego zamiaru. Brudny filtr powietrza i przegrzane świece psują osiągi, ale nie odbierają bezpieczeństwa ruchu."},"3856":{"text":"Za słaby nacisk na pedał nie wykorzystuje przyczepności opon i wydłuża drogę hamowania. Blokowanie kół i utrata sterowności to skutek nacisku zbyt mocnego w aucie bez ABS."},"3857":{"text":"Bez ABS zbyt mocne hamowanie blokuje koła, a zablokowane koła nie prowadzą auta. Kierownica przestaje działać i pojazd jedzie prosto tam, gdzie niósł go rozpęd."},"3858":{"text":"W aucie z ABS hamuje się szybko i mocno, a układ sam pilnuje, żeby koła się nie zablokowały. Pulsacyjne naciskanie tylko przeszkadza ABS, bo powtarza to, co on robi lepiej."},"3859":{"text":"Pulsowanie pedału to znak, że ABS pracuje, więc trzymaj nacisk do końca hamowania. Zmniejszenie siły nacisku wydłuża drogę hamowania, a puszczenie pedału przerywa je zupełnie."},"3860":{"text":"ABS nie pozwala kołom się zablokować, więc auto daje się kierować także wtedy, gdy hamujesz podczas bocznego poślizgu. Działa zawsze, nie tylko na prostej albo tylko na łuku."},"3861":{"text":"Jeśli na wzniesieniu puścisz hamulec awaryjny, zanim sprzęgło zacznie przenosić napęd, auto stoczy się do tyłu. Hamulec zwalnia się dopiero wtedy, gdy czuć, że pojazd chce ruszyć."},"3882":{"text":"Czerwona lampka układu hamulcowego oznacza usterkę hamulców, więc trzeba się zatrzymać i sprawdzić poziom płynu. Dalsza jazda może skończyć się brakiem hamulców."},"3885":{"text":"Czerwona lampka układu chłodzenia ostrzega, że płyn chłodniczy jest za gorący. Trzeba się zatrzymać i ostudzić silnik, bo przegrzanie kończy się poważną awarią."},"3889":{"text":"Plamy płynów na miejscu postoju to objaw nieszczelności układu, na przykład hamulcowego albo chłodzenia. Bezbarwne spaliny są normalne, a lampka ładowania przed uruchomieniem silnika też."},"3890":{"text":"Czarne albo niebieskie gęste spaliny oznaczają, że silnik pali za dużo paliwa lub oleju. Bezbarwne spaliny są normalne, a lampka ciśnienia oleju przed uruchomieniem silnika świeci się zawsze."},"3891":{"text":"Koło dojazdowe wolno używać krótko i z ograniczoną prędkością, po to właśnie jest w aucie. Zużyte klocki lub tarcze i uszkodzone amortyzatory wykluczają pojazd z ruchu."},"4160":{"law":"art. 30 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Przy widoczności poniżej 50 metrów wolno włączyć tylne światła przeciwmgłowe, żeby jadący z tyłu zauważyli auto wcześniej. Światła drogowe odbijają się od mgły, a zmniejszanie odstępu jest wprost niebezpieczne."},"4362":{"text":"Najbardziej ślisko jest na początku deszczu, gdy woda miesza się z kurzem i olejem na jezdni. Po dłuższym opadzie ta warstwa zostaje spłukana i przyczepność częściowo wraca."},"4364":{"text":"Im szybciej jedziesz, tym węższy staje się kąt widzenia: wzrok skupia się na punkcie daleko przed autem. Dlatego przy dużej prędkości łatwo przeoczyć pieszego albo pojazd z boku."},"4367":{"text":"Pole widzenia ogranicza oślepienie światłami nadjeżdżających pojazdów: oko potrzebuje kilku sekund, żeby wrócić do normy. Lusterko wewnętrzne i klimatyzacja widoczności nie zabierają."},"4368":{"text":"Źle ustawione światła oświetlają za krótki odcinek drogi albo świecą w bok, więc nocą po prostu nie widzisz tego, co przed autem. Ustawienie reflektorów sprawdza się przy badaniu technicznym."},"4369":{"text":"Alkohol zawęża pole widzenia do tak zwanego widzenia tunelowego, więc kierowca przestaje dostrzegać to, co po bokach. Mruganie i przerwa na odpoczynek działają odwrotnie, poprawiają uwagę."},"4370":{"text":"Fotel ustawiony za nisko albo za wysoko zabiera część widoku drogi: słupki i maska zasłaniają wtedy więcej, niż powinny. Okulary przeciwsłoneczne w słońcu pomagają, a nie przeszkadzają."},"4371":{"text":"Wraz ze wzrostem prędkości kąt widzenia się zwęża, bo wzrok skupia się coraz dalej przed autem. Przy 50 km/h widzisz szeroko, przy 130 km/h praktycznie tylko wąski korytarz."},"4374":{"text":"Na każdym biegu rozpędzaj się na tyle, żeby po zmianie na wyższy silnik nie dławił się i nie szarpał. Kręcenie do odcięcia to strata paliwa, a przeskakiwanie o dwa biegi dusi silnik."},"4375":{"law":"art. 61 ust. 3 Prawa o ruchu drogowym","text":"Rowery wolno wozić na bagażniku dachowym, bo nie zasłaniają wtedy świateł ani tablicy rejestracyjnej. Uchwyt z tyłu jest dozwolony tylko wtedy, gdy tablica i światła pozostają widoczne."},"4472":{"law":"art. 81 Prawa o ruchu drogowym","text":"Badania techniczne mają znaczenie przez cały okres używania pojazdu, bo hamulce, zawieszenie i światła zużywają się niezależnie od gwarancji. Gwarancja dotyczy napraw, nie bezpieczeństwa w ruchu."},"4495":{"text":"ABS nie pozwala kołom się zablokować podczas hamowania, dzięki czemu auto daje się kierować i nie traci stabilności. Nie chroni jednak przed poślizgiem przy każdej prędkości i nie pomaga w zakrętach."},"4534":{"text":"Na śniegu wszystko robi się płynnie, bez gwałtownych ruchów kierownicą, bo przyczepność jest minimalna. Wyłączanie kontroli trakcji i przyspieszanie na podjeździe kończą się buksowaniem i poślizgiem."},"4562":{"law":"art. 162 Kodeksu karnego","text":"Odpowiada każdy, kto mógł pomóc bez narażania siebie lub innych na utratę życia albo ciężki uszczerbek. Obowiązek nie ogranicza się do lekarzy ani do uczestników zdarzenia."},"4563":{"text":"Poszkodowanego wyciąga się z pojazdu tylko wtedy, gdy inaczej nie da się ratować życia, na przykład przy zatrzymaniu krążenia albo pożarze. Bez takiej potrzeby przenoszenie grozi dodatkowym urazem kręgosłupa."},"4578":{"text":"Dyspozytor musi wiedzieć przede wszystkim, gdzie doszło do zdarzenia oraz ilu jest poszkodowanych i w jakim są stanie. Od tego zależy, ile i jakich zespołów wyśle."},"4579":{"text":"Płonące ubranie gasi się, kładąc człowieka na ziemi i tłumiąc ogień kurtką lub kocem, żeby odciąć dopływ powietrza. Gaśnica proszkowa dodatkowo uszkadza drogi oddechowe i oparzoną skórę."},"4592":{"text":"Bez działających świateł stop jadący z tyłu nie wie, że hamujesz, więc pojazdu nie wolno używać. Czujniki parkowania i klimatyzacja nie mają wpływu na bezpieczeństwo ruchu."},"4593":{"text":"Czerwona lampka ciśnienia oleju oznacza, że silnik pracuje bez smarowania, więc zatrzymaj się i natychmiast go wyłącz. Kilkanaście sekund dalszej jazdy potrafi zatrzeć silnik."},"4600":{"text":"112 jest wspólnym numerem alarmowym: łączy z pogotowiem, strażą i policją naraz. Działa w całej Polsce i w całej Unii Europejskiej, także z telefonu bez karty SIM."},"6318":{"text":"Alkohol zmienia pole widzenia: zawęża je i osłabia widzenie peryferyjne oraz ocenę odległości. Kierowca patrzy wprost przed siebie i nie rejestruje pieszego wchodzącego z boku."},"6340":{"text":"Poduszka powietrzna zmniejsza obrażenia, ale nie chroni w pełni i działa tylko razem z zapiętym pasem. Nadwozia auta poduszka nie chroni w ogóle, od tego są strefy zgniotu."},"6361":{"law":"art. 51 ust. 3 Prawa o ruchu drogowym","text":"Świateł drogowych nie wolno używać, gdy z przeciwka nadjeżdża inny pojazd, bo oślepiają jego kierowcę. Deszcz i wjazd do miasta same z siebie takiego obowiązku nie tworzą."},"6362":{"law":"art. 51 ust. 3 Prawa o ruchu drogowym","text":"Na światła mijania przełącza się zawsze wtedy, gdy można oślepić kierującego jadącego z przodu, także przez jego lusterka. Sam widok poprzedzającego auta w oddali obowiązku jeszcze nie tworzy."},"6378":{"text":"Dobrze ustawione lusterko zewnętrzne pokazuje obszar za pojazdem i wąski pasek jego boku, który służy za punkt odniesienia. Samego boku auta albo tylko sąsiedniego pasa jest za mało."},"6442":{"text":"Światła pozycyjne pokazują innym, gdzie stoi lub jedzie pojazd i jak jest szeroki. Drogi nie oświetlają, a do sygnalizowania zmiany pasa służą kierunkowskazy."},"6443":{"text":"Reflektory ustawione za wysoko świecą w oczy kierowcom nadjeżdżającym z przeciwka. Na zużycie paliwa ani żarówek ustawienie reflektorów nie ma wpływu."},"6451":{"text":"Reflektory ustawione za nisko oświetlają zaledwie kilka metrów przed autem, więc nocą widzisz drogę znacznie gorzej. Na zużycie paliwa i żarówek nie mają wpływu."},"6463":{"text":"Wyziębionego człowieka wezwij pomoc, przenieś w ciepłe miejsce, okryj i ogrzewaj powoli. Gorący napój i alkohol rozszerzają naczynia skóry i przyspieszają utratę ciepła z wnętrza ciała."},"7445":{"law":"art. 60 ust. 2 pkt 4 Prawa o ruchu drogowym","text":"Ciągnięcie za pojazdem dzieci na sankach jest zabronione. Przyczepa lekka jest dozwolona, a holowanie innego auta w obszarze zabudowanym również."},"7446":{"law":"art. 19 ust. 3b Prawa o ruchu drogowym","text":"Stojąc w zatorze w tunelu trzeba zostawić co najmniej 5 metrów do poprzedzającego pojazdu. Ten odstęp służy służbom ratowniczym do dojazdu i pozwala wyjechać, gdyby wybuchł pożar."},"7447":{"law":"art. 45 ust. 2 pkt 1 Prawa o ruchu drogowym","text":"Zabronione jest rozmawianie przez telefon trzymany w ręku. Radio i nawigacja są dozwolone, o ile ich obsługa nie odrywa uwagi od drogi."},"7451":{"law":"art. 61 ust. 8 Prawa o ruchu drogowym","text":"Ładunek wystający z tyłu oznacza się czerwoną chorągiewką albo tarczą, a po zmroku dodatkowo czerwonym światłem i odblaskiem. Czerwień jest w ruchu drogowym barwą ostrzegawczą od tyłu."},"7452":{"text":"Rzeczywista masa całkowita przyczepy nie może przekroczyć rzeczywistej masy całkowitej samochodu, który ją ciągnie. Cięższa przyczepa zaczyna prowadzić auto zamiast być prowadzoną."},"7454":{"law":"art. 31 ust. 2 pkt 5 Prawa o ruchu drogowym","text":"Na autostradzie holowanie jest zabronione, poza odholowaniem pojazdem do tego przeznaczonym do najbliższego wyjazdu. Na drodze ekspresowej i w strefie zamieszkania holować wolno."},"7457":{"law":"art. 61 ust. 6 Prawa o ruchu drogowym","text":"Łańcuchy zakłada się tylko na drogę pokrytą śniegiem. Na gołym asfalcie niszczą nawierzchnię i oponę, a sama data w kalendarzu ani temperatura o tym nie decydują."},"7461":{"text":"Najdłuższa droga hamowania jest na lodzie, bo przyczepność opon jest tam kilkakrotnie mniejsza niż na suchym asfalcie. Mokra droga wydłuża hamowanie, ale nie tak drastycznie jak oblodzona."},"7463":{"text":"ABS pozwala zachować kontrolę nad autem przy gwałtownym hamowaniu, bo koła się nie blokują i kierownica dalej działa. Drogi hamowania nie skraca zawsze: na żwirze czy śniegu potrafi ją nawet wydłużyć."},"7465":{"law":"art. 46 ust. 2 Prawa o ruchu drogowym","text":"Pojazd zostawiony na wzniesieniu trzeba zabezpieczyć przed stoczeniem: hamulec postojowy, bieg i koła skręcone w stronę krawężnika. Sam wrzucony bieg na stromym podjeździe bywa za mało."},"7512":{"law":"art. 31 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Holowany pojazd oznacza się trójkątem odblaskowym umieszczonym z tyłu po lewej stronie, a w warunkach ograniczonej widoczności dodatkowo włączonymi światłami. Same światła awaryjne tego nie zastępują."},"7513":{"law":"art. 78 ust. 4 Prawa o ruchu drogowym","text":"Właściciel ma obowiązek wskazać, komu powierzył pojazd, i uwalnia go tylko sytuacja, w której auto zostało użyte wbrew jego woli i wiedzy, a on nie mógł temu zapobiec. Prowadzenie działalności gospodarczej z tego obowiązku nie zwalnia."},"7515":{"law":"art. 60 ust. 1 pkt 2 Prawa o ruchu drogowym","text":"Jazda z niewidoczną tablicą rejestracyjną jest zabroniona, bo pojazdu nie da się zidentyfikować. Zasłonięcie tablicy przez ładunek nie jest usprawiedliwieniem, ładunek trzeba przewieźć inaczej."},"7516":{"text":"Nalepka z oznaczeniem innego państwa niż kraj rejestracji jest zabroniona, bo wprowadza w błąd co do pochodzenia pojazdu. Tablica z symbolem PL niczego tu nie zmienia."},"7518":{"text":"Szybsze miganie kontrolki to standardowy sygnał, że jedna z żarówek kierunkowskazu się przepaliła. Sprawdza się więc żarówki, a nie akumulator, bo pozostałe odbiorniki działają normalnie."},"7519":{"text":"Poziom oleju sprawdza się na zimnym silniku przed jazdą albo po kilku minutach od wyłączenia, gdy olej spłynie do miski. Pomiar zaraz po zgaszeniu albo przy pracującym silniku daje zaniżony wynik."},"7708":{"text":"Na suchej nawierzchni rusza się na pierwszym biegu, bo daje największą siłę napędową. Drugi bieg nadaje się tylko na bardzo śliskiej drodze, gdy chcesz ograniczyć poślizg kół."},"8320":{"law":"art. 24 ust. 5 Prawa o ruchu drogowym","text":"Pojazd szynowy wyprzedza się co do zasady z prawej strony, ale na jezdni jednokierunkowej wolno zrobić to także z lewej. Na jezdni jednokierunkowej nie ma ruchu z przeciwka, więc manewr jest bezpieczny."},"9012":{"text":"Na ostrość widzenia kierowca wpływa sam: przez koncentrację, samopoczucie i stan zdrowia, w tym zmęczenie i wzrok. Pogoda, nawierzchnia i pora doby są warunkami zewnętrznymi, na które wpływu nie ma."},"9035":{"text":"Im większa prędkość, tym węższe pole widzenia: przy 40 km/h obejmuje około stu stopni, przy 130 km/h zaledwie kilkadziesiąt. Dlatego na szybkiej drodze łatwo przeoczyć to, co dzieje się z boku."},"9058":{"law":"art. 60 ust. 2 pkt 2 Prawa o ruchu drogowym","text":"Nadmierna emisja spalin i nadmierny hałas są zabronione wszędzie, nie tylko w mieście czy w strefie zamieszkania. Przepis chroni środowisko i ludzi na całej sieci dróg."},"9065":{"text":"ASR działa przy przekazywaniu napędu na koła, więc pomaga przy nagłym przyspieszeniu na mokrej nawierzchni. Podczas zjazdu ze wzniesienia koła nie są napędzane i układ nie ma czego korygować."},"9067":{"text":"ASR najbardziej przydaje się przy gwałtownym ruszaniu na śliskiej nawierzchni, bo wtedy koła napędowe buksują. Przy zjeździe albo równomiernej jeździe pod górę nie ma poślizgu, który miałby ograniczać."},"9068":{"text":"ESP wkracza tam, gdzie auto przestaje trzymać zadany tor, czyli na ostrym zakręcie. Przy stałej prędkości albo na prostej nie ma czego stabilizować."},"9070":{"text":"Kilka zakrętów jeden po drugim to typowa sytuacja, w której nadwozie się rozkołysuje i ESP koryguje tor jazdy. Utrzymanie stałej prędkości to zadanie tempomatu, a nie ESP."}};
